#!/usr/bin/env ruby
# Numerical screenshots are generated by the capture scripts, not synthesized.
# This deterministic catalogue makes the same verified image available to cards,
# article social metadata, and the publication helper.
require "cgi"
require "date"
require "digest"
require "json"
require "yaml"

module BlogSummaryImages
  ROOT = File.expand_path("..", __dir__)
  META_START = "<!-- Generated numerical summary image: start -->"
  META_END = "<!-- Generated numerical summary image: end -->"
  JPEG_SOF = [0xc0, 0xc1, 0xc2, 0xc3, 0xc5, 0xc6, 0xc7, 0xc9, 0xca, 0xcb, 0xcd, 0xce, 0xcf].freeze

  def self.experiments(root = ROOT)
    result = {}
    Dir.glob(File.join(root, "blog/_posts/*.md")).sort.each do |path|
      text = File.read(path, encoding: "UTF-8")
      front, body = text.match(/\A---\s*\n(.*?)\n---\s*\n(.*)\z/m)&.captures
      raise "Missing post metadata: #{path}" unless front
      metadata = YAML.safe_load(front, permitted_classes: [Date, Time]) || {}
      next unless metadata["figure"] || body.match?(/<(?:iframe|canvas)\b/i)
      slug = File.basename(path, ".md").sub(/\A\d{4}-\d{2}-\d{2}-/, "")
      raise "Duplicate experiment slug: #{slug}" if result.key?(slug)
      result[slug] = { "kind" => "published", "path" => path }
    end
    Dir.glob(File.join(root, "blog/preparations/*.html")).sort.each do |path|
      text = File.read(path, encoding: "UTF-8")
      next unless text.match?(/<(?:iframe|canvas)\b/i)
      slug = File.basename(path, ".html")
      raise "Duplicate experiment slug: #{slug}" if result.key?(slug)
      result[slug] = { "kind" => "forthcoming", "path" => path }
    end
    result.sort.to_h
  end

  def self.jpeg_dimensions(bytes)
    raise "Not a JPEG" unless bytes.start_with?("\xff\xd8\xff".b)
    cursor = 2
    dimensions = nil
    while cursor < bytes.bytesize
      raise "Invalid JPEG marker" unless bytes.getbyte(cursor) == 0xff
      cursor += 1
      cursor += 1 while bytes.getbyte(cursor) == 0xff
      marker = bytes.getbyte(cursor)
      raise "Truncated JPEG marker" unless marker
      cursor += 1
      break if marker == 0xda || marker == 0xd9
      next if marker == 0x01 || (0xd0..0xd7).cover?(marker)
      raise "Private JPEG metadata must be stripped" if (0xe1..0xef).cover?(marker) || marker == 0xfe
      length = bytes.byteslice(cursor, 2)&.unpack1("n")
      raise "Truncated JPEG segment" unless length && length >= 2 && cursor + length <= bytes.bytesize
      if JPEG_SOF.include?(marker)
        raise "Invalid JPEG dimensions" if length < 8
        height, width = bytes.byteslice(cursor + 3, 4).unpack("nn")
        dimensions = [width, height]
      end
      cursor += length
    end
    raise "JPEG has no dimensions" unless dimensions && dimensions.all?(&:positive?)
    raise "Truncated JPEG image" unless bytes.end_with?("\xff\xd9".b)
    dimensions
  end

  def self.catalogue(root = ROOT)
    manifest = JSON.parse(File.read(File.join(root, "blog/summary-images.json"), encoding: "UTF-8"))
    raise "Unsupported summary-image manifest" unless manifest["version"] == 1 && manifest["images"].is_a?(Hash)
    actual = manifest.fetch("images")
    expected = experiments(root).keys
    missing, extra = expected - actual.keys, actual.keys - expected
    raise "Summary-image coverage differs: missing #{missing.join(', ')}; extra #{extra.join(', ')}" unless missing.empty? && extra.empty?
    actual.sort.to_h.each do |slug, image|
      raise "Invalid experiment slug" unless slug.match?(/\A[a-z0-9]+(?:-[a-z0-9]+)*\z/)
      raise "Wrong image path: #{slug}" unless image["path"] == "/blog/imgs/summaries/#{slug}.jpg"
      raise "Missing image description: #{slug}" unless image["alt"].is_a?(String) && !image["alt"].strip.empty?
      raise "Invalid capture source: #{slug}" unless image["source"].is_a?(String) && image["source"].start_with?("/blog/") && !image["source"].include?("..")
      raise "Missing capture settings: #{slug}" unless image["settings"].is_a?(Hash)
      raise "Invalid image digest: #{slug}" unless image["sha256"].to_s.match?(/\A[0-9a-f]{64}\z/)
      bytes = File.binread(File.join(root, image.fetch("path").delete_prefix("/")))
      raise "Image exceeds the 1 MB attachment limit: #{slug}" if bytes.bytesize > 1_000_000
      raise "Image digest differs: #{slug}" unless Digest::SHA256.hexdigest(bytes) == image["sha256"]
      raise "Image dimensions differ: #{slug}" unless jpeg_dimensions(bytes) == image.values_at("width", "height")
    end
    { "version" => 1, "images" => actual.sort.to_h }
  end

  def self.escape(value)
    CGI.escapeHTML(value.to_s)
  end

  def self.preview_metadata(text, image)
    text = text.gsub(/\n?#{Regexp.escape(META_START)}.*?#{Regexp.escape(META_END)}\n?/m, "")
    url = "https://www.gpeyre.com#{image.fetch('path')}"
    block = <<~HTML
      #{META_START}
      <meta property="og:image" content="#{escape(url)}">
      <meta property="og:image:alt" content="#{escape(image.fetch('alt'))}">
      <meta property="og:image:width" content="#{image.fetch('width')}">
      <meta property="og:image:height" content="#{image.fetch('height')}">
      <meta name="twitter:card" content="summary_large_image">
      <meta name="twitter:image" content="#{escape(url)}">
      <meta name="twitter:image:alt" content="#{escape(image.fetch('alt'))}">
      #{META_END}
    HTML
    raise "Preview has no closing head" unless text.match?(%r{</head>}i)
    text.sub(%r{</head>}i) { "\n#{block}</head>" }
  end

  def self.preview_index(text, images)
    text.gsub(/(<a class="draft-card" href="([a-z0-9-]+)\.html">)(.*?)(<\/a>)/m) do
      opening, slug, body, closing = Regexp.last_match.captures
      body = body.gsub(/<img class="draft-summary-image"[^>]*>\n?/, "")
      image = images[slug]
      if image
        path = "../#{image.fetch('path').delete_prefix('/blog/')}"
        body = %(<img class="draft-summary-image" src="#{escape(path)}" alt="#{escape(image.fetch('alt'))}" width="#{image.fetch('width')}" height="#{image.fetch('height')}" loading="lazy" decoding="async">) + body
      end
      opening + body + closing
    end
  end

  def self.outputs(root = ROOT)
    data = catalogue(root)
    images = data.fetch("images")
    result = { File.join(root, "_data/blog_summary_images.json") => JSON.pretty_generate(data) + "\n" }
    experiments(root).each do |slug, record|
      next unless record.fetch("kind") == "forthcoming"
      result[record.fetch("path")] = preview_metadata(File.read(record.fetch("path"), encoding: "UTF-8"), images.fetch(slug))
    end
    index = File.join(root, "blog/preparations/index.html")
    result[index] = preview_index(File.read(index, encoding: "UTF-8"), images)
    result
  end
end

if $PROGRAM_NAME == __FILE__
  abort "Usage: ruby scripts/build-blog-summary-images.rb [--check]" unless ARGV.empty? || ARGV == ["--check"]
  outputs = BlogSummaryImages.outputs
  stale = outputs.keys.reject { |path| File.exist?(path) && File.read(path, encoding: "UTF-8") == outputs.fetch(path) }
  if ARGV == ["--check"]
    abort "Summary-image integration is stale: #{stale.map { |path| path.delete_prefix(BlogSummaryImages::ROOT + '/') }.join(', ')}. Run ruby scripts/build-blog-summary-images.rb." unless stale.empty?
    puts "Summary images, preview cards, and social metadata are current (#{BlogSummaryImages.experiments.length} experiments)."
  else
    stale.each { |path| File.write(path, outputs.fetch(path)) }
    puts "Integrated #{BlogSummaryImages.experiments.length} numerical summary images."
  end
end
